END;
$function$

CREATE OR REPLACE FUNCTION api.fulfillment_options(target_store uuid, delivery_pincode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE shop app.stores; area app.delivery_areas;
BEGIN
 SELECT s.* INTO shop FROM app.stores s JOIN app.businesses b ON b.id=s.business_id
 WHERE s.id=target_store AND s.is_active AND s.deleted_at IS NULL AND b.is_active AND b.deleted_at IS NULL;
 IF shop.id IS NULL THEN RETURN jsonb_build_object('homeDelivery',false,'storePickup',false); END IF;
 IF shop.delivery_enabled AND delivery_pincode ~ '^[1-9][0-9]{5}$' THEN
  SELECT * INTO area FROM app.delivery_areas WHERE business_id=shop.business_id AND store_id=shop.id AND pincode=delivery_pincode AND is_active; END IF;
 RETURN jsonb_build_object('homeDelivery',area.id IS NOT NULL,'storePickup',shop.pickup_enabled,
 'deliveryRule',CASE WHEN area.id IS NOT NULL THEN jsonb_build_object('id',area.id,'pincode',area.pincode,'name',area.name,
 'feePaise',area.delivery_fee_paise,'minimumOrderPaise',area.minimum_order_paise,'version',area.version) ELSE NULL END);
END;
$function$

CREATE OR REPLACE FUNCTION api.save_category(target_id uuid, category_name text, parent uuid, sort integer, active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor app.staff_profiles; result uuid;
BEGIN
 actor := app.require_staff(ARRAY['ADMIN']);
 -- Serialize category hierarchy changes; prevent indirect cycles.
 PERFORM 1 FROM app.businesses WHERE id=actor.business_id FOR UPDATE;
 IF parent IS NOT NULL AND (parent=target_id OR NOT EXISTS(SELECT 1 FROM app.categories WHERE id=parent AND business_id=actor.business_id)) THEN RAISE EXCEPTION 'Invalid parent'; END IF;
 IF target_id IS NOT NULL AND EXISTS (
 WITH RECURSIVE ancestors AS (SELECT id,parent_id FROM app.categories WHERE id=parent AND business_id=actor.business_id
 UNION SELECT c.id,c.parent_id FROM app.categories c JOIN ancestors a ON c.id=a.parent_id)
 SELECT 1 FROM ancestors WHERE id=target_id) THEN RAISE EXCEPTION 'Category cycle'; END IF;
 IF target_id IS NULL THEN
 INSERT INTO app.categories(business_id,name,parent_id,sort_order,is_active) VALUES(actor.business_id,btrim(category_name),parent,sort,active) RETURNING id INTO result;
 ELSE UPDATE app.categories SET name=btrim(category_name),parent_id=parent,sort_order=sort,is_active=active WHERE id=target_id AND business_id=actor.business_id RETURNING id INTO result;
 END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 INSERT INTO app.staff_access_audit(business_id,actor_id,action,target_id,detail) VALUES(actor.business_id,actor.id,'CATEGORY_SAVED',result,jsonb_build_object('active',active));
 RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION api.save_delivery_area(target_id uuid, target_store uuid, expected_version bigint, area_pincode text, area_name text, fee_paise bigint, minimum_paise bigint, active boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor app.staff_profiles; previous app.delivery_areas; result app.delivery_areas;
BEGIN
 actor:=app.require_staff(ARRAY['ADMIN','OWNER']);
 IF NOT app.can_access_store(actor.business_id,target_store) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF target_id IS NULL THEN
  IF expected_version IS NOT NULL THEN RAISE EXCEPTION 'New rule must not supply a version' USING ERRCODE='22023'; END IF;
  INSERT INTO app.delivery_areas(business_id,store_id,pincode,name,delivery_fee_paise,minimum_order_paise,is_active)
  VALUES(actor.business_id,target_store,area_pincode,btrim(area_name),fee_paise,minimum_paise,active) RETURNING * INTO result;
 ELSE
  SELECT * INTO previous FROM app.delivery_areas WHERE id=target_id AND business_id=actor.business_id AND store_id=target_store FOR UPDATE;
  IF previous.id IS NULL THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
  IF expected_version IS NULL OR previous.version<>expected_version THEN RAISE EXCEPTION 'Delivery rule changed; reload' USING ERRCODE='40001'; END IF;
  UPDATE app.delivery_areas SET pincode=area_pincode,name=btrim(area_name),delivery_fee_paise=fee_paise,minimum_order_paise=minimum_paise,is_active=active
  WHERE id=previous.id RETURNING * INTO result;
 END IF;
 INSERT INTO app.staff_access_audit(business_id,actor_id,action,target_id,detail)
 VALUES(actor.business_id,actor.id,'DELIVERY_AREA_SAVED',result.id,
 jsonb_build_object('storeId',target_store,'pincode',result.pincode,'oldFeePaise',previous.delivery_fee_paise,
 'feePaise',result.delivery_fee_paise,'oldMinimumPaise',previous.minimum_order_paise,'minimumPaise',result.minimum_order_paise,
 'wasActive',previous.is_active,'active',result.is_active,'version',result.version));
 RETURN result.id;
END;
$function$

CREATE OR REPLACE FUNCTION api.save_preparation_option(target_id uuid, option_name text, active boolean, display_order integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor app.staff_profiles; result uuid;
BEGIN
 actor:=app.require_staff(ARRAY['ADMIN']);
 -- Match save_product's lock order (products before preparation records).
 PERFORM 1 FROM app.products WHERE business_id=actor.business_id ORDER BY id FOR UPDATE;
 IF target_id IS NULL THEN
 INSERT INTO app.preparation_options(business_id,name,is_active,sort_order) VALUES(actor.business_id,btrim(option_name),active,display_order) RETURNING id INTO result;
 ELSE
 UPDATE app.preparation_options SET name=btrim(option_name),is_active=active,sort_order=display_order
 WHERE id=target_id AND business_id=actor.business_id RETURNING id INTO result;
 END IF;
 IF result IS NULL THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 -- Preserve the legacy input cache after a reusable preparation rename.
 UPDATE app.products p SET preparations=(
 SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object('name',o.name,'cleaning_loss_percent',pp.cleaning_loss_percent)) ORDER BY pp.sort_order,pp.id)
 FROM app.product_preparation_options pp JOIN app.preparation_options o ON o.id=pp.preparation_option_id
 WHERE pp.product_id=p.id AND pp.is_active)
 WHERE p.business_id=actor.business_id AND EXISTS(SELECT 1 FROM app.product_preparation_options pp WHERE pp.product_id=p.id AND pp.preparation_option_id=result AND pp.is_active);
 INSERT INTO app.staff_access_audit(business_id,actor_id,action,target_id,detail) VALUES(actor.business_id,actor.id,'PREPARATION_SAVED',result,jsonb_build_object('active',active));
 RETURN result;
END;
$function$

