CREATE OR REPLACE FUNCTION api.update_daily_product(offering uuid, expected_version integer, price_paise bigint, is_available boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor app.staff_profiles; old_row app.product_store_settings; old_price bigint;
BEGIN
 actor := app.require_staff(ARRAY['ADMIN','OWNER']);
 IF price_paise IS NULL OR price_paise NOT BETWEEN 1 AND 100000000 OR is_available IS NULL OR expected_version IS NULL THEN
 RAISE EXCEPTION 'Invalid daily product values' USING ERRCODE='22023'; END IF;
 SELECT o.* INTO old_row FROM app.product_store_settings o JOIN app.products p ON p.id=o.product_id JOIN app.categories c ON c.id=p.category_id
 WHERE o.id=offering AND o.business_id=actor.business_id AND p.is_active AND c.is_active AND o.is_active AND app.category_is_visible(p.category_id,p.business_id) FOR UPDATE OF o;
 IF old_row.id IS NULL OR NOT app.can_access_store(actor.business_id,old_row.store_id) THEN RAISE EXCEPTION 'Forbidden' USING ERRCODE='42501'; END IF;
 IF old_row.version <> expected_version THEN RAISE EXCEPTION 'Product changed; reload before saving' USING ERRCODE='40001'; END IF;
 SELECT price_per_kg_paise INTO old_price FROM app.product_prices WHERE offering_id=offering ORDER BY offering_version DESC LIMIT 1;
 IF old_price IS NOT DISTINCT FROM price_paise AND old_row.available = is_available THEN RETURN; END IF;
 UPDATE app.product_store_settings SET available=is_available,version=version+1,updated_at=pg_catalog.clock_timestamp() WHERE id=offering;
 IF old_price IS DISTINCT FROM price_paise THEN
 INSERT INTO app.product_prices(business_id,offering_id,price_per_kg_paise,offering_version,created_by)
 VALUES(actor.business_id,offering,price_paise,old_row.version+1,actor.id);
 END IF;
 INSERT INTO app.staff_access_audit(business_id,actor_id,action,target_id,detail)
 VALUES(actor.business_id,actor.id,'DAILY_PRODUCT_UPDATED',offering,jsonb_build_object('oldPricePaise',old_price,'pricePaise',price_paise,'wasAvailable',old_row.available,'available',is_available));
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_assignment_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.store_id IS DISTINCT FROM OLD.store_id
     OR NEW.staff_profile_id IS DISTINCT FROM OLD.staff_profile_id THEN
    RAISE EXCEPTION 'Assignment identity is immutable; deactivate it instead' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_customer_delivery_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_TABLE_NAME='customers' THEN
  NEW.mobile_e164:=app.normalize_indian_mobile(NEW.mobile_e164);
  IF TG_OP='UPDATE' AND OLD.auth_user_id IS NOT NULL AND
   (NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id OR NEW.mobile_e164 IS DISTINCT FROM OLD.mobile_e164
    OR NEW.mobile_verified_at IS DISTINCT FROM OLD.mobile_verified_at) THEN
   RAISE EXCEPTION 'Verified identity changes require a reviewed recovery workflow' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='customer_addresses' THEN
  NEW.recipient_mobile_e164:=app.normalize_indian_mobile(NEW.recipient_mobile_e164);
  IF TG_OP='UPDATE' AND NEW.customer_id IS DISTINCT FROM OLD.customer_id THEN
   RAISE EXCEPTION 'Address owner is immutable' USING ERRCODE='23514'; END IF;
 ELSE
  IF TG_OP='UPDATE' AND (NEW.store_id IS DISTINCT FROM OLD.store_id OR NEW.pincode IS DISTINCT FROM OLD.pincode) THEN
   RAISE EXCEPTION 'Delivery rule identity is immutable; deactivate and create a new rule' USING ERRCODE='23514'; END IF;
  IF TG_OP='INSERT' THEN NEW.version:=1; ELSE NEW.version:=OLD.version+1; END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_row_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Hard deletion is forbidden; retire or deactivate this record' USING ERRCODE = '23514';
  ELSIF TG_OP = 'INSERT' THEN
    NEW.created_at := pg_catalog.statement_timestamp();
    NEW.updated_at := NEW.created_at;
  ELSE
    IF NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'Internal identity is immutable' USING ERRCODE = '23514';
    END IF;
    IF TG_TABLE_NAME <> 'businesses' THEN
      IF NEW.business_id IS DISTINCT FROM OLD.business_id THEN
        RAISE EXCEPTION 'Business identity is immutable' USING ERRCODE = '23514';
      END IF;
    END IF;
    NEW.created_at := OLD.created_at;
    NEW.updated_at := GREATEST(OLD.updated_at, pg_catalog.statement_timestamp());
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_settings_revision()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN NEW.revision := 1;
  ELSE NEW.revision := OLD.revision + 1;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.guard_staff_authority()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  IF OLD.is_active AND OLD.role = 'OWNER' AND (
    NOT NEW.is_active OR NEW.role <> 'OWNER'
    OR NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id
    OR NEW.disabled_at IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Active OWNER removal is locked until the reviewed admin mutation phase' USING ERRCODE = '23514';
  END IF;
  IF OLD.auth_user_id IS NOT NULL AND NEW.auth_user_id IS DISTINCT FROM OLD.auth_user_id
     AND (NEW.auth_user_id IS NOT NULL OR NEW.is_active) THEN
    RAISE EXCEPTION 'Auth identity may only be unlinked from an inactive profile' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END;
$function$

