CREATE OR REPLACE FUNCTION app.normalize_indian_mobile(value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE digits text;
BEGIN
 IF value IS NULL OR length(value)>40 OR value !~ '^[+0-9 ()-]+$' THEN
  RAISE EXCEPTION 'Invalid Indian mobile number' USING ERRCODE='22023'; END IF;
 digits:=regexp_replace(value,'[ ()-]','','g');
 IF digits ~ '^[6-9][0-9]{9}$' THEN RETURN '+91'||digits;
 ELSIF digits ~ '^0[6-9][0-9]{9}$' THEN RETURN '+91'||substr(digits,2);
 ELSIF digits ~ '^91[6-9][0-9]{9}$' THEN RETURN '+'||digits;
 ELSIF digits ~ '^\+91[6-9][0-9]{9}$' THEN RETURN digits; END IF;
 RAISE EXCEPTION 'Invalid Indian mobile number' USING ERRCODE='22023';
END;
$function$

CREATE OR REPLACE FUNCTION app.require_staff(allowed_roles text[])
 RETURNS app.staff_profiles
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor app.staff_profiles;
BEGIN
 SELECT * INTO actor FROM app.staff_profiles WHERE id = app.current_staff_profile_id();
 IF actor.id IS NULL OR NOT (app.current_staff_role() = ANY(allowed_roles)) THEN
  RAISE EXCEPTION 'Forbidden' USING ERRCODE = '42501';
 END IF;
 RETURN actor;
END;
$function$

CREATE OR REPLACE FUNCTION app.sync_product_catalogue()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE item jsonb; ordinal bigint; prep uuid;
BEGIN
 IF TG_OP='INSERT' OR NEW.allowed_weights IS DISTINCT FROM OLD.allowed_weights THEN
 UPDATE app.product_allowed_weights SET is_active=false WHERE product_id=NEW.id AND business_id=NEW.business_id;
 FOR item,ordinal IN SELECT value,ordinality FROM jsonb_array_elements(NEW.allowed_weights) WITH ORDINALITY LOOP
  INSERT INTO app.product_allowed_weights(business_id,product_id,raw_weight_grams,sort_order)
  VALUES(NEW.business_id,NEW.id,(item::text)::integer,ordinal::integer-1)
  ON CONFLICT(business_id,product_id,raw_weight_grams) DO UPDATE SET is_active=true,sort_order=EXCLUDED.sort_order;
 END LOOP;
 END IF;
 IF TG_OP='INSERT' OR NEW.preparations IS DISTINCT FROM OLD.preparations THEN
 UPDATE app.product_preparation_options SET is_active=false WHERE product_id=NEW.id AND business_id=NEW.business_id;
 FOR item,ordinal IN SELECT value,ordinality FROM jsonb_array_elements(NEW.preparations) WITH ORDINALITY LOOP
  INSERT INTO app.preparation_options(business_id,name)
  VALUES(NEW.business_id,btrim(item->>'name'))
  ON CONFLICT(business_id,lower(name)) DO NOTHING;
  SELECT id INTO prep FROM app.preparation_options WHERE business_id=NEW.business_id AND lower(name)=lower(btrim(item->>'name'));
  INSERT INTO app.product_preparation_options(business_id,product_id,preparation_option_id,cleaning_loss_percent,sort_order)
  VALUES(NEW.business_id,NEW.id,prep,(item->>'cleaning_loss_percent')::numeric,ordinal::integer-1)
  ON CONFLICT(business_id,product_id,preparation_option_id) DO UPDATE
  SET is_active=true,cleaning_loss_percent=EXCLUDED.cleaning_loss_percent,sort_order=EXCLUDED.sort_order;
 END LOOP;
 END IF;
 IF TG_OP='INSERT' OR NEW.image_path IS DISTINCT FROM OLD.image_path THEN
  UPDATE app.product_images SET is_active=false,is_primary=false WHERE product_id=NEW.id AND legacy;
  IF NEW.image_path<>'' THEN
   UPDATE app.product_images SET is_primary=false WHERE product_id=NEW.id AND is_primary;
   INSERT INTO app.product_images(business_id,product_id,asset_path,alt_text,is_primary,legacy)
   VALUES(NEW.business_id,NEW.id,NEW.image_path,NEW.name,true,true)
   ON CONFLICT(business_id,product_id) WHERE legacy DO UPDATE
   SET asset_path=EXCLUDED.asset_path,alt_text=EXCLUDED.alt_text,is_active=true,is_primary=true;
  END IF;
 END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION app.valid_opening_hours(value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE
  day_entry record;
  slot jsonb;
  opens text;
  closes text;
  previous_close text;
BEGIN
  IF value IS NULL OR pg_catalog.jsonb_typeof(value) <> 'object'
     OR pg_catalog.octet_length(value::text) > 8192 THEN
    RETURN false;
  END IF;
  FOR day_entry IN SELECT key, val FROM pg_catalog.jsonb_each(value) AS d(key, val) LOOP
    IF day_entry.key NOT IN ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun')
       OR pg_catalog.jsonb_typeof(day_entry.val) <> 'array' THEN
      RETURN false;
    END IF;
    IF pg_catalog.jsonb_array_length(day_entry.val) > 4 THEN RETURN false; END IF;
    previous_close := NULL;
    FOR slot IN SELECT v FROM pg_catalog.jsonb_array_elements(day_entry.val) AS s(v) LOOP
      IF pg_catalog.jsonb_typeof(slot) <> 'object' THEN RETURN false; END IF;
      IF NOT (slot ? 'opens' AND slot ? 'closes')
         OR (slot - 'opens' - 'closes') <> '{}'::jsonb
         OR pg_catalog.jsonb_typeof(slot -> 'opens') IS DISTINCT FROM 'string'
         OR pg_catalog.jsonb_typeof(slot -> 'closes') IS DISTINCT FROM 'string' THEN
        RETURN false;
      END IF;
      opens := slot ->> 'opens';
      closes := slot ->> 'closes';
      IF opens !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
         OR closes !~ '^(([01][0-9]|2[0-3]):[0-5][0-9]|24:00)$'
         OR opens COLLATE pg_catalog."C" >= closes COLLATE pg_catalog."C"
         OR (previous_close IS NOT NULL AND opens COLLATE pg_catalog."C" < previous_close COLLATE pg_catalog."C") THEN
        RETURN false;
      END IF;
      previous_close := closes;
    END LOOP;
  END LOOP;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION app.valid_product_configuration(weights jsonb, preparations jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE item jsonb;
BEGIN
 IF jsonb_typeof(weights) IS DISTINCT FROM 'array' OR jsonb_typeof(preparations) IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 IF jsonb_array_length(weights) NOT BETWEEN 1 AND 50 OR jsonb_array_length(preparations) NOT BETWEEN 1 AND 50 THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(weights) LOOP
  IF jsonb_typeof(item) <> 'number' OR item::text !~ '^[0-9]+$' OR (item::text)::numeric NOT BETWEEN 1 AND 100000 THEN RETURN false; END IF;
 END LOOP;
 IF (SELECT count(DISTINCT value) FROM jsonb_array_elements(weights)) <> jsonb_array_length(weights) THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(preparations) LOOP
  IF jsonb_typeof(item) <> 'object' OR (item - 'name' - 'cleaning_loss_percent') <> '{}'::jsonb
   OR jsonb_typeof(item->'name') IS DISTINCT FROM 'string' OR length(btrim(item->>'name')) NOT BETWEEN 1 AND 100 THEN RETURN false; END IF;
  IF item ? 'cleaning_loss_percent' THEN
   IF jsonb_typeof(item->'cleaning_loss_percent') IS DISTINCT FROM 'number' THEN RETURN false; END IF;
   IF (item->>'cleaning_loss_percent')::numeric < 0 OR (item->>'cleaning_loss_percent')::numeric >= 100 THEN RETURN false; END IF;
  END IF;
 END LOOP;
 RETURN (SELECT count(DISTINCT lower(btrim(value->>'name'))) FROM jsonb_array_elements(preparations)) = jsonb_array_length(preparations);
END;
$function$

CREATE OR REPLACE FUNCTION app.validate_guest_fulfillment(target_store uuid, fulfillment_method text, mobile text, customer_name text, delivery_address jsonb, subtotal_paise bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE normalized_mobile text; options jsonb; address jsonb; item record; max_length integer;
BEGIN
 normalized_mobile:=app.normalize_indian_mobile(mobile);
 IF subtotal_paise IS NULL OR subtotal_paise NOT BETWEEN 0 AND 1000000000000 THEN RAISE EXCEPTION 'Invalid trusted subtotal' USING ERRCODE='22023'; END IF;
 IF customer_name IS NOT NULL AND (length(btrim(customer_name))>160 OR customer_name !~ '[^[:space:]]') THEN RAISE EXCEPTION 'Invalid name' USING ERRCODE='22023'; END IF;
 IF fulfillment_method='HOME_DELIVERY' THEN
  IF customer_name IS NULL OR length(btrim(customer_name))=0 THEN RAISE EXCEPTION 'Delivery name required' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(delivery_address) IS DISTINCT FROM 'object' OR octet_length(delivery_address::text)>4096
   OR (delivery_address - ARRAY['line1','line2','locality','city','state','pincode','countryCode'])<>'{}'::jsonb THEN
   RAISE EXCEPTION 'Invalid delivery address' USING ERRCODE='22023'; END IF;
  address:='{}'::jsonb;
  FOR item IN SELECT key,value FROM jsonb_each(delivery_address) LOOP
   IF jsonb_typeof(item.value) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION 'Address values must be text' USING ERRCODE='22023'; END IF;
   max_length:=CASE WHEN item.key IN ('line1','line2') THEN 240 ELSE 120 END;
   IF length(btrim(item.value #>> '{}')) NOT BETWEEN 1 AND max_length OR (item.value #>> '{}') !~ '[^[:space:]]' THEN
    RAISE EXCEPTION 'Invalid address field' USING ERRCODE='22023'; END IF;
   address:=address||jsonb_build_object(item.key,btrim(item.value #>> '{}'));
  END LOOP;
  IF NOT(address ?& ARRAY['line1','city','state','pincode']) OR (address->>'pincode') !~ '^[1-9][0-9]{5}$'
   OR (address ? 'countryCode' AND address->>'countryCode'<>'IN') THEN RAISE EXCEPTION 'Complete Indian address required' USING ERRCODE='22023'; END IF;
  address:=address||jsonb_build_object('countryCode','IN');
  options:=api.fulfillment_options(target_store,address->>'pincode');
  IF NOT (options->>'homeDelivery')::boolean THEN RAISE EXCEPTION 'Home Delivery unavailable' USING ERRCODE='22023'; END IF;
  IF subtotal_paise<(options->'deliveryRule'->>'minimumOrderPaise')::bigint THEN RAISE EXCEPTION 'Delivery minimum not met' USING ERRCODE='22023'; END IF;
 ELSIF fulfillment_method='STORE_PICKUP' THEN
  options:=api.fulfillment_options(target_store,NULL);
  IF NOT (options->>'storePickup')::boolean THEN RAISE EXCEPTION 'Store Pickup unavailable' USING ERRCODE='22023'; END IF;
  address:=NULL;
 ELSE RAISE EXCEPTION 'Invalid fulfillment method' USING ERRCODE='22023'; END IF;
 RETURN jsonb_build_object('storeId',target_store,'method',fulfillment_method,'mobileE164',normalized_mobile,
 'name',btrim(customer_name),'address',address,'deliveryRule',options->'deliveryRule');
END;
$function$
